using System.Collections.Generic;
using UnityEngine;

namespace VerdantSiege.Data
{
    /// <summary>Registry of all shipped content (stable ids for saves and lookups). Generated by the editor setup.</summary>
    [CreateAssetMenu(menuName = "Verdant Siege/Content Database", fileName = "ContentDatabase")]
    public sealed class ContentDatabase : ScriptableObject
    {
        public List<DefenderDefinition> defenders = new List<DefenderDefinition>();
        public List<EnemyDefinition> enemies = new List<EnemyDefinition>();
        public List<EncounterDefinition> encounters = new List<EncounterDefinition>();

        public EncounterDefinition FindEncounter(string id)
        {
            foreach (EncounterDefinition e in encounters) if (e != null && e.id == id) return e;
            return null;
        }

        public DefenderDefinition FindDefender(string id)
        {
            foreach (DefenderDefinition d in defenders) if (d != null && d.id == id) return d;
            return null;
        }

        public EnemyDefinition FindEnemy(string id)
        {
            foreach (EnemyDefinition d in enemies) if (d != null && d.id == id) return d;
            return null;
        }
    }
}
